 check("All 16 multiplicity mappings retain typed composite key components",combinations);
 auto recursive=m;recursive.logical={};auto relation=recursive.get("contiene");relation->identifying=false;relation->a=relation->b="ordine";relation->roleA="parent";relation->roleB="child";auto recursiveSchema=generateLogical(recursive,{},errors);check("Recursive 1:N copies the original key type",errors.isEmpty()&&consistent(recursiveSchema));relation->cardA=relation->cardB="0,N";recursiveSchema=generateLogical(recursive,{},errors);check("Recursive N:M copies key type to both roles",errors.isEmpty()&&consistent(recursiveSchema));
