 auto before=w.model.json();auto typesAction=w.findChild<QAction*>("showDataTypes");bool shown=w.nodes["data"]->label.contains(": Data");typesAction->trigger();check("Show types toggles labels without changing model data",shown&&!w.showTypes&&w.nodes["data"]->label=="Data"&&before==w.model.json());typesAction->trigger();
 w.model=typedModel;w.history.clear();w.notationBox->setCurrentIndex(1);w.refresh();w.fit();qApp->processEvents();check("UML attribute rows display generic types",w.nodes["data"]->label.contains(": Data"));w.selectOnly("data");qApp->processEvents();check("Conceptual type selector is visible after selection",w.formWidget->findChild<QComboBox*>("genericType")->isVisible());w.grab().save(output+"/tipi-concettuale-it.png");
 w.uml=false;w.refresh();w.fit();check("Typed PDF export follows visible diagram labels",w.exportPdf(output+"/Ordini-tipi-Chen.pdf",QPageSize::A3,true,true,error));
 w.switchLevel(true);auto pkId=bySource(w.logicalCache,"numordine")->id;auto pkName=bySource(w.logicalCache,"numordine")->name;w.selectOnly(pkId);combo=w.formWidget->findChild<QComboBox*>("genericType");combo->setCurrentIndex(combo->findData("string"));w.formWidget->findChild<QPushButton*>("applyLogicalProperties")->click();qApp->processEvents();check("Logical selector customizes PK and updates FK without editing conceptual type",bySource(w.logicalCache,"numordine")->dataType=="string"&&bySource(w.logicalCache,"numordine")->typeOverride&&consistent(w.logicalCache)&&w.model.get("numordine")->dataType=="integer");w.history.undo();check("Undo restores logical key type and all dependent FK types",bySource(w.logicalCache,"numordine")->dataType=="integer"&&consistent(w.logicalCache));w.history.redo();
 w.applyLogicalProperties(pkId,pkName,false,"__inherit");check("Inherited option removes logical override",!bySource(w.logicalCache,"numordine")->typeOverride&&bySource(w.logicalCache,"numordine")->dataType=="integer"&&consistent(w.logicalCache));
 QString fkId=w.logicalCache.tables[1].foreignKeys[0].columns[0];w.selectOnly(fkId);combo=w.formWidget->findChild<QComboBox*>("genericType");check("Generated FK inspector keeps type selector read-only",combo&&!combo->isEnabled()&&combo->currentData()=="integer");
 auto dataId=bySource(w.logicalCache,"data")->id;w.selectOnly(dataId);combo=w.formWidget->findChild<QComboBox*>("genericType");combo->setCurrentIndex(combo->findData(QString("")));w.formWidget->findChild<QPushButton*>("applyLogicalProperties")->click();qApp->processEvents();check("Actual UI can set an explicit unspecified logical type",bySource(w.logicalCache,"data")->typeOverride&&bySource(w.logicalCache,"data")->dataType.isEmpty());
 w.applyLogicalProperties(dataId,"Data",true,"__inherit");w.selectOnly(dataId);w.en=true;w.mode=2;w.applyTheme();w.buildMenus();w.refresh();w.fit();qApp->processEvents();combo=w.formWidget->findChild<QComboBox*>("genericType");check("English type selector and logical labels use generic Real",combo&&combo->itemText(combo->findData("real"))=="Real"&&combo->itemText(0).startsWith("Inherited:")&&w.nodes[dataId]->label.contains(": Date"));w.grab().save(output+"/tipi-logico-en-notte.png");
 auto legacyLogical=generateLogical(legacy,{},errors);legacy.logical=legacyLogical.json();check("Untyped logical file still uses v2 and original conceptual digest",legacy.json()["version"]==2&&legacyLogical.sourceDigest==digest);
